package main

import "net/http"

func onboardingPage(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(`<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Бадди — первая задача</title>
<style>body{font:17px system-ui;max-width:760px;margin:40px auto;padding:20px;color:#17212c}section{padding:24px;border:1px solid #d7dce2;border-radius:16px;margin:20px 0}input,button{font:inherit;padding:12px;margin:8px 0;display:block;max-width:100%;box-sizing:border-box}button{cursor:pointer;background:#1263df;color:white;border:0;border-radius:8px}button:disabled{opacity:.5}#error{color:#a01d25}small{color:#536270}</style>
<h1>Первая задача с бадди</h1><p>Проверим, что нужно для вашей команды, и пройдём путь к первой задаче.</p>
<section id="login"><h2>Войти</h2><form id="login-form"><label>Логин<input name="username" autocomplete="username" required></label><label>Пароль<input name="password" type="password" autocomplete="current-password" required></label><button>Войти</button></form></section>
<section id="scenario" hidden><p id="message"></p><small id="status"></small><div id="widget"></div><button id="start">Начать путь к первой задаче</button><button id="logout">Выйти</button></section><p id="error" role="alert"></p>
<script>
function newIdempotencyKey(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,byte=>byte.toString(16).padStart(2,'0')).join('')}
let token='',state=null,pendingKey='';const el=id=>document.getElementById(id);
async function call(path,body,idem){const headers={'Content-Type':'application/json'};if(token)headers.Authorization='Bearer '+token;if(idem)headers['Idempotency-Key']=idem;const res=await fetch(path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await res.json();if(!res.ok){if(res.status===401){token='';el('login').hidden=false;el('scenario').hidden=true}throw Error(typeof data.error==='string'?data.error:data.error?.message||'Не удалось выполнить запрос')}return data}
async function run(fn){el('error').textContent='';document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn()}catch(e){el('error').textContent=e.message}finally{document.querySelectorAll('button').forEach(b=>b.disabled=false)}}
function render(s){state=s;localStorage.setItem('buddy-scenario-id',s.scenario_id);el('message').textContent=s.message;el('status').textContent='Состояние: '+s.status;el('start').hidden=true;const root=el('widget');root.replaceChildren();if(!s.widget.visible)return;
if(s.widget.type==='access_request_form'){const form=document.createElement('form'),label=document.createElement('label'),input=document.createElement('input'),confirmLabel=document.createElement('label'),confirm=document.createElement('input'),send=document.createElement('button');label.textContent='Зачем нужен доступ к '+s.widget.resource.name;input.required=true;input.minLength=2;input.maxLength=1000;label.append(input);confirm.type='checkbox';confirm.required=true;confirmLabel.append(confirm,document.createTextNode('Подтверждаю отправку заявки'));send.textContent='Отправить заявку';form.append(label,confirmLabel,send);form.onsubmit=e=>{e.preventDefault();run(async()=>{if(!pendingKey)pendingKey=newIdempotencyKey();const result=await call('/v1/scenarios/'+state.scenario_id+'/access-requests',{revision:state.revision,reason:input.value,confirmed:confirm.checked,form_values:{}},pendingKey);pendingKey='';render(result)})};root.append(form)}
const refresh=document.createElement('button');refresh.textContent='Проверить текущий доступ';refresh.onclick=()=>run(async()=>render(await call('/v1/scenarios/'+state.scenario_id+'/advance',{revision:state.revision})));root.append(refresh);
if(s.widget.type==='approval_status'){const info=document.createElement('p');info.textContent='Заявка: '+(s.widget.request_id||'ожидается');root.prepend(info)}}
el('login-form').onsubmit=e=>{e.preventDefault();run(async()=>{const form=new FormData(e.target),result=await call('/v1/scenarios/login',{username:form.get('username'),password:form.get('password')});token=result.access_token;sessionStorage.setItem('team-access-token',token);e.target.reset();el('login').hidden=true;el('scenario').hidden=false;const id=localStorage.getItem('buddy-scenario-id');if(id){try{render(await call('/v1/scenarios/'+encodeURIComponent(id)))}catch(e){if(!token)throw e;localStorage.removeItem('buddy-scenario-id');el('start').hidden=false}}})};
el('start').onclick=()=>run(async()=>render(await call('/v1/scenarios',{})));el('logout').onclick=()=>{token='';sessionStorage.removeItem('team-access-token');state=null;pendingKey='';localStorage.removeItem('buddy-scenario-id');el('login').hidden=false;el('scenario').hidden=true;el('widget').replaceChildren();el('start').hidden=false};
setInterval(async()=>{if(!token||!state||state.status!=='waiting_access')return;try{const updated=await call('/v1/scenarios/'+state.scenario_id);if(updated.revision!==state.revision)render(updated)}catch(e){el('error').textContent=e.message}},5000);
</script></html>`))
}
